import { getAdminParams } from "@/lib/admin-params"

declare global {
  interface Window {
    google?: any
    mapsvgReactGoogleMapsPromise?: Promise<void>
    mapsvgReactGoogleMapsReady?: () => void
    gm_authFailure?: () => void
  }
}

function googleApiKey(): string {
  const options = getAdminParams().options
  if (!options || typeof options !== "object") return ""
  const key = (options as Record<string, unknown>).google_api_key
  return typeof key === "string" ? key.trim() : ""
}

/** One loader per document; iframe callers retain Google's own stylesheet scope. */
export function loadGoogleMapsApiOnce(target: Window = window, signal?: AbortSignal): Promise<void> {
  if (signal?.aborted) return Promise.reject(signal.reason)
  if (target.google?.maps?.Geocoder) return Promise.resolve()
  if (target.mapsvgReactGoogleMapsPromise) return target.mapsvgReactGoogleMapsPromise
  const key = googleApiKey()
  if (!key) return Promise.reject(new Error("Google Maps API key is not configured. Add it in Settings → General."))

  const doc = target.document
  const existing = Array.from(doc.scripts).find((script) => script.src.includes("maps.googleapis.com/maps/api/js"))
  const script = existing ?? doc.createElement("script")
  const previousAuth = target.gm_authFailure
  const previousReady = target.mapsvgReactGoogleMapsReady
  target.mapsvgReactGoogleMapsPromise = new Promise<void>((resolve, reject) => {
    let settled = false
    let poll: ReturnType<typeof setInterval> | undefined
    let timeout: ReturnType<typeof setTimeout> | undefined
    const cleanup = () => {
      if (poll) clearInterval(poll)
      if (timeout) clearTimeout(timeout)
      signal?.removeEventListener("abort", aborted)
      script.removeEventListener("load", ready)
      script.removeEventListener("error", failed)
      if (target.gm_authFailure === authFailure) target.gm_authFailure = previousAuth
      if (target.mapsvgReactGoogleMapsReady === ready) target.mapsvgReactGoogleMapsReady = previousReady
    }
    const finish = (error?: Error) => {
      if (settled) return
      settled = true
      cleanup()
      if (error) {
        // An owned failed script must not prevent a fresh load on retry.
        if (!existing) script.remove()
        reject(error)
      } else resolve()
    }
    const ready = () => {
      if (target.google?.maps?.Geocoder) finish()
    }
    const aborted = () => finish(signal?.reason ?? new DOMException("Google Maps closed.", "AbortError"))
    const failed = () => finish(new Error("Google Maps API failed to load."))
    const authFailure = () => {
      finish(new Error("Google Maps API key is incorrect or is not authorized for this site."))
      previousAuth?.()
    }
    target.gm_authFailure = authFailure
    target.mapsvgReactGoogleMapsReady = ready
    signal?.addEventListener("abort", aborted, { once: true })
    if (existing) script.addEventListener("load", ready)
    script.addEventListener("error", failed)
    // A foreign loader can already have emitted load, or become ready after it.
    if (existing) poll = setInterval(ready, 50)
    timeout = setTimeout(() => finish(new Error("Google Maps API took too long to load. Please try again.")), 30000)
    if (!existing) {
      script.async = true
      script.defer = true
      script.dataset.mapsvgReactGoogleMaps = "1"
      script.src = "https://maps.googleapis.com/maps/api/js?loading=async&callback=mapsvgReactGoogleMapsReady&key=" + encodeURIComponent(key)
      doc.head.appendChild(script)
    }
    if (existing) ready()
  }).catch((error) => {
    target.mapsvgReactGoogleMapsPromise = undefined
    throw error
  })
  return target.mapsvgReactGoogleMapsPromise
}
