import frameHtml from "./admin-frame.html?raw"
import { getAdminParams } from "@/lib/admin-params"

/** Google authorizes the document URL, so its SDK must not run in about:srcdoc. */
export function adminFrameUrl(): string {
  const { pluginUrl, version } = getAdminParams()
  if (!pluginUrl) throw new Error("The preview frame URL is unavailable. Reload the editor.")
  const base = new URL(pluginUrl.replace(/\/?$/, "/"), document.baseURI)
  if (base.origin !== window.location.origin || !["http:", "https:"].includes(base.protocol)) {
    throw new Error("The preview frame must use this site's origin.")
  }
  const url = new URL("js/mapsvg-admin-frame.html", base)
  if (version) url.searchParams.set("v", version)
  return url.href
}

/** document.open inherits the caller URL; retain that same-origin identity without a pending navigation. */
export function initializeAdminFrame(iframe: HTMLIFrameElement): void {
  const url = adminFrameUrl()
  const doc = iframe.contentDocument
  const frame = iframe.contentWindow
  if (!doc || !frame) throw new Error("The preview frame is unavailable.")
  iframe.removeAttribute("srcdoc")
  doc.open()
  doc.write(frameHtml)
  doc.close()
  frame.history.replaceState(null, "", url)
  if (doc.URL !== url) throw new Error("The preview frame URL could not initialize.")
}
